        internal static int Div(int a, int b) => Mul(a, Inv(b));

        internal static int Inv(int a) => _Inv[a];

        private static int Mod1(int a) => a + (int)((uint)a >> 24);

        private static int Mod2(uint a) => Mod1((int)a - HqcParameters.GF_MUL_ORDER);

        private static int Mod(uint a) => Mod2((a & 0xFF) + (a >> 8));

        internal static int Mul(int a, int b)
        {
            int m = (-a & -b) >> 31; // { a, b } != 0
            return m & _Exp[Mod2((uint)_Log[a] + _Log[b])];
        }

        internal static int Mul3(int a, int b, int c)
        {
            int m = (-a & -b & -c) >> 31; // { a, b, c } != 0
            return m & _Exp[Mod((uint)_Log[a] + _Log[b] + _Log[c])];
        }

        internal static int Sqr(int a) => _Sqr[a];
    }
